import{_ as e,o as s,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"72. Using Valgrind for Memory Checking","description":"The Little Book of C — 72. Using Valgrind for Memory Checking","frontmatter":{"title":"72. Using Valgrind for Memory Checking","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 72. Using Valgrind for Memory Checking","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":72,"sidebarWeight":72,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking.md"};function p(l,a,o,r,d,c){return s(),n("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking)</p><p>If gdb helps you see how your program runs, Valgrind helps you see where it leaks. C gives you raw control over memory, and that means you’re responsible for every allocation, deallocation, and pointer access.</p><p>Valgrind is your best friend when you need to find:</p><ul><li>Memory leaks (forgotten<code>free()</code>)</li><li>Invalid reads/writes</li><li>Double frees</li><li>Use-after-free errors</li></ul><p>Let’s learn how to use it to make your programs solid and leak-free.</p><h4 id="step-1-installing-valgrind" tabindex="-1">Step 1. Installing Valgrind <a class="header-anchor" href="#step-1-installing-valgrind" aria-label="Permalink to &quot;Step 1. Installing Valgrind&quot;">​</a></h4><p>On Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install valgrind</span></span></code></pre></div><p>On macOS (with Homebrew):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install valgrind</span></span></code></pre></div><p>Compile your program with debug symbols:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g memory.c -o memory</span></span></code></pre></div><h4 id="step-2-running-with-valgrind" tabindex="-1">Step 2. Running with Valgrind <a class="header-anchor" href="#step-2-running-with-valgrind" aria-label="Permalink to &quot;Step 2. Running with Valgrind&quot;">​</a></h4><p>Run your program under Valgrind:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind ./memory</span></span></code></pre></div><p>Valgrind runs your program inside a virtual CPU and monitors every memory operation. At the end, it prints a detailed report of allocations and leaks.</p><h4 id="step-3-a-simple-example" tabindex="-1">Step 3. A Simple Example <a class="header-anchor" href="#step-3-a-simple-example" aria-label="Permalink to &quot;Step 3. A Simple Example&quot;">​</a></h4><p>Here’s a program with two common mistakes: a leak and an invalid free.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    p[10] = 42;  // invalid write (out of bounds)</span></span>
<span class="line"><span>    return 0;    // forgot to free(p)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g mem_bug.c -o mem_bug</span></span>
<span class="line"><span>valgrind ./mem_bug</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid write of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (mem_bug.c:6)</span></span>
<span class="line"><span>==1234==  Address 0x5201048 is 0 bytes after a block of size 40 alloc&#39;d</span></span>
<span class="line"><span>==1234==    at 0x484186F: malloc (vg_replace_malloc.c:380)</span></span>
<span class="line"><span>==1234==</span></span>
<span class="line"><span>==1234== HEAP SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 40 bytes in 1 blocks</span></span>
<span class="line"><span>==1234== LEAK SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 40 bytes in 1 blocks</span></span></code></pre></div><p>Valgrind caught both the invalid access and the leak.</p><h4 id="step-4-fixing-the-errors" tabindex="-1">Step 4. Fixing the Errors <a class="header-anchor" href="#step-4-fixing-the-errors" aria-label="Permalink to &quot;Step 4. Fixing the Errors&quot;">​</a></h4><p>Correct version:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    if (!p) return 1;</span></span>
<span class="line"><span>    p[9] = 42;   // valid index</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run again:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind ./mem_bug</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== All heap blocks were freed -- no leaks are possible</span></span>
<span class="line"><span>== ERROR SUMMARY: 0 errors from 0 contexts</span></span></code></pre></div><p>Clean and perfect.</p><h4 id="step-5-detecting-use-after-free" tabindex="-1">Step 5. Detecting Use-After-Free <a class="header-anchor" href="#step-5-detecting-use-after-free" aria-label="Permalink to &quot;Step 5. Detecting Use-After-Free&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(sizeof(int));</span></span>
<span class="line"><span>    *p = 5;</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *p); // using freed memory</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Valgrind says:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid read of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (use_after_free.c:7)</span></span>
<span class="line"><span>==1234==  Address 0x5201040 is 0 bytes inside a block of size 4 free&#39;d</span></span></code></pre></div><p>It even shows where the block was freed.</p><h4 id="step-6-detecting-double-free" tabindex="-1">Step 6. Detecting Double Free <a class="header-anchor" href="#step-6-detecting-double-free" aria-label="Permalink to &quot;Step 6. Detecting Double Free&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(4);</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Valgrind output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid free() / delete / delete[]</span></span>
<span class="line"><span>==1234==    at 0x4845DEF: free (vg_replace_malloc.c:872)</span></span>
<span class="line"><span>==1234==  Address 0x5201040 was freed previously</span></span></code></pre></div><h4 id="step-7-memory-leak-categories" tabindex="-1">Step 7. Memory Leak Categories <a class="header-anchor" href="#step-7-memory-leak-categories" aria-label="Permalink to &quot;Step 7. Memory Leak Categories&quot;">​</a></h4><p>Valgrind divides leaks into categories:</p><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td>definitely lost</td><td>No pointer to the block remains, true leak</td></tr><tr><td>indirectly lost</td><td>Referenced by a leaked block</td></tr><tr><td>possibly lost</td><td>Pointer may exist but Valgrind can’t confirm</td></tr><tr><td>still reachable</td><td>Program ended but memory wasn’t freed (often harmless)</td></tr></tbody></table><h4 id="step-8-getting-a-clean-report" tabindex="-1">Step 8. Getting a Clean Report <a class="header-anchor" href="#step-8-getting-a-clean-report" aria-label="Permalink to &quot;Step 8. Getting a Clean Report&quot;">​</a></h4><p>To check for true leaks only:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --leak-check=full --show-leak-kinds=definite ./program</span></span></code></pre></div><p>For more verbose tracking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --track-origins=yes ./program</span></span></code></pre></div><p>That flag tells you where an uninitialized variable first appeared.</p><h4 id="step-9-checking-for-stack-or-uninitialized-values" tabindex="-1">Step 9. Checking for Stack or Uninitialized Values <a class="header-anchor" href="#step-9-checking-for-stack-or-uninitialized-values" aria-label="Permalink to &quot;Step 9. Checking for Stack or Uninitialized Values&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x;</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x); // uninitialized read</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Valgrind output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Use of uninitialised value of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (uninit.c:5)</span></span></code></pre></div><p>Always initialize your variables!</p><h4 id="step-10-tiny-code-leak-detector" tabindex="-1">Step 10. Tiny Code: Leak Detector <a class="header-anchor" href="#step-10-tiny-code-leak-detector" aria-label="Permalink to &quot;Step 10. Tiny Code: Leak Detector&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void leak1(void) { malloc(100); }</span></span>
<span class="line"><span>void leak2(void) { char *p = malloc(50); free(p); }</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    leak1();</span></span>
<span class="line"><span>    leak2();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --leak-check=full ./leaks</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== 100 bytes in 1 blocks are definitely lost in loss record 1 of 1</span></span>
<span class="line"><span>==1234== LEAK SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 100 bytes in 1 blocks</span></span></code></pre></div><p>Only<code>leak1()</code> forgot to<code>free()</code>, Valgrind pinpointed it exactly.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Valgrind helps you:</p><ul><li>Find hidden memory leaks</li><li>Detect invalid pointer usage</li><li>Catch uninitialized values</li><li>Write safer, cleaner, more reliable C</li></ul><p>It’s an essential tool in your workflow, especially for long-running programs, servers, or systems software.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Write a program that allocates multiple blocks and forgets to free one.</p><p>Intentionally use<code>p[10]</code> on a<code>malloc(10)</code> block.</p><p>Trigger a use-after-free and find it in Valgrind.</p><p>Use<code>--track-origins=yes</code> to trace uninitialized data.</p><p>Refactor your code until Valgrind reports:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>All heap blocks were freed -- no leaks are possible</span></span></code></pre></div><p>Next, you’ll explore Assertions and Defensive Programming, techniques to catch logic errors before they reach runtime crashes.</p>`,74)])])}const u=e(t,[["render",p]]);export{h as __pageData,u as default};
